@Override public String telnet(Channel channel, String message) { if (message == null || message.length() == 0) { return "Please input service name, eg: 
cd XxxService
cd com.xxx.XxxService"; } StringBuilder buf = new StringBuilder(); if (message.equals("/") || message.equals("..")) { String service = (String) channel.getAttribute(SERVICE_KEY); channel.removeAttribute(SERVICE_KEY); buf.append("Cancelled default service " + service + "."); } else { boolean found = false; for (Exporter<?> exporter : DubboProtocol.getDubboProtocol().getExporters()) { if (message.equals(exporter.getInvoker().getInterface().getSimpleName()) || message.equals(exporter.getInvoker().getInterface().getName()) || message.equals(exporter.getInvoker().getUrl().getPath())) { found = true; break; } } if (found) { channel.setAttribute(SERVICE_KEY, message); buf.append("Used the " + message + " as default.
You can cancel default service by command: cd /"); } else { buf.append("No such service " + message); } } return buf.toString(); }

@Override public String telnet(Channel channel, String message) { if (message == null || message.length() == 0) { return "Please input service name, eg: 
cd XxxService
cd com.xxx.XxxService"; } StringBuilder buf = new StringBuilder(); if (message.equals("/") || message.equals("..")) { String service = (String) channel.getAttribute(SERVICE_KEY); channel.removeAttribute(SERVICE_KEY); buf.append("Cancelled default service " + service + "."); } else { boolean found = false; for (Exporter<?> exporter : DubboProtocol.getDubboProtocol().getExporters()) { if (message.equals(exporter.getInvoker().getInterface().getSimpleName()) || message.equals(exporter.getInvoker().getInterface().getName()) || message.equals(exporter.getInvoker().getUrl().getPath())) { found = true; break; } } if (found) { channel.setAttribute(SERVICE_KEY, message); buf.append("Used the " + message + " as default.
You can cancel default service by command: cd /"); } else { buf.append("No such service " + message); } } return buf.toString(); }

@Override public String telnet(Channel channel, String message) { StringBuilder buf = new StringBuilder(); String service = null; boolean detail = false; if (message.length() > 0) { String[] parts = message.split("\s+"); for (String part : parts) { if ("-l".equals(part)) { detail = true; } else { if (service != null && service.length() > 0) { return "Invaild parameter " + part; } service = part; } } } else { service = (String) channel.getAttribute(ChangeTelnetHandler.SERVICE_KEY); if (service != null && service.length() > 0) { buf.append("Use default service " + service + ".
"); } } if (service == null || service.length() == 0) { for (Exporter<?> exporter : DubboProtocol.getDubboProtocol().getExporters()) { if (buf.length() > 0) { buf.append("
"); } buf.append(exporter.getInvoker().getInterface().getName()); if (detail) { buf.append(" -> "); buf.append(exporter.getInvoker().getUrl()); } } } else { Invoker<?> invoker = null; for (Exporter<?> exporter : DubboProtocol.getDubboProtocol().getExporters()) { if (service.equals(exporter.getInvoker().getInterface().getSimpleName()) || service.equals(exporter.getInvoker().getInterface().getName()) || service.equals(exporter.getInvoker().getUrl().getPath())) { invoker = exporter.getInvoker(); break; } } if (invoker != null) { Method[] methods = invoker.getInterface().getMethods(); for (Method method : methods) { if (buf.length() > 0) { buf.append("
"); } if (detail) { buf.append(ReflectUtils.getName(method)); } else { buf.append(method.getName()); } } } else { buf.append("No such service " + service); } } return buf.toString(); }

