@Test public void testAggregateFunction() throws InitializationException { final MockRecordParser parser = new MockRecordParser(); parser.addSchemaField("name", RecordFieldType.STRING); parser.addSchemaField("points", RecordFieldType.INT); parser.addRecord("Tom", 1); parser.addRecord("Jerry", 2); parser.addRecord("Tom", 99); final MockRecordWriter writer = new MockRecordWriter(""name","points""); TestRunner runner = getRunner(); runner.addControllerService("parser", parser); runner.enableControllerService(parser); runner.addControllerService("writer", writer); runner.enableControllerService(writer); runner.setProperty(REL_NAME, "select name, sum(points) as points from FLOWFILE GROUP BY name"); runner.setProperty(QueryRecord.RECORD_READER_FACTORY, "parser"); runner.setProperty(QueryRecord.RECORD_WRITER_FACTORY, "writer"); runner.enqueue(""); runner.run(); runner.assertTransferCount(REL_NAME, 1); final MockFlowFile flowFileOut = runner.getFlowFilesForRelationship(REL_NAME).get(0); flowFileOut.assertContentEquals(""name","points"
"Tom","100"
"Jerry","2"
"); }

@Test public void testSendData() throws IOException, InitializationException { PrometheusRecordSink sink = initTask(); List<RecordField> recordFields = Arrays.asList( new RecordField("field1", RecordFieldType.INT.getDataType()), new RecordField("field2", RecordFieldType.DECIMAL.getDecimalDataType(30, 10)), new RecordField("field3", RecordFieldType.STRING.getDataType()) ); RecordSchema recordSchema = new SimpleRecordSchema(recordFields); Map<String, Object> row1 = new HashMap<>(); row1.put("field1", 15); row1.put("field2", BigDecimal.valueOf(12.34567D)); row1.put("field3", "Hello"); Map<String, Object> row2 = new HashMap<>(); row2.put("field1", 6); row2.put("field2", BigDecimal.valueOf(0.1234567890123456789D)); row2.put("field3", "World!"); RecordSet recordSet = new ListRecordSet(recordSchema, Arrays.asList( new MapRecord(recordSchema, row1), new MapRecord(recordSchema, row2) )); Map<String, String> attributes = new HashMap<>(); attributes.put("a", "Hello"); WriteResult writeResult = sink.sendData(recordSet, attributes, true); assertNotNull(writeResult); assertEquals(2, writeResult.getRecordCount()); assertEquals("Hello", writeResult.getAttributes().get("a")); final String content = getMetrics(); assertTrue(content.contains("field1{field3="Hello",} 15.0
field1{field3="World!",} 6.0
")); assertTrue(content.contains("field2{field3="Hello",} 12.34567
field2{field3="World!",} 0.12345678901234568
")); try { sink.onStopped(); } catch (Exception e) { } }

