@Test public void testABCStringBuilder() { String A = "A: "hi", # This is an A
"; String B = "B: 'hi', # This is a B
"; String C = "C: hi, # And that's a C
"; @NotNull Wire wire = createWire(); StringBuilder sb = new StringBuilder(); wire.commentListener(s -> sb.append(s).append('
')); ABC abc = new ABC(); for (String input : new String[] { A + B + C, B + A + C, C + A + B, A + C + B, B + C + A, C + B + A }) { wire.reset(); wire.bytes().append(input); assertEquals(input, "!net.openhft.chronicle.wire.TextWireTest$ABC {
" + " A: hi,
" + " B: hi,
" + " C: hi
" + "}
", wire.getValueIn() .object(abc, ABC.class) .toString()); assertEquals(sb.toString(), Arrays.asList("This is an A", "This is a B"), Arrays.stream(sb.toString().split("
")).sorted(Collections.reverseOrder()).collect(toList())); sb.setLength(0); } }

