@Test public void testNestedList() { NestedList nl = Marshallable.fromString("!" + NestedList.class.getName() + " {
" + " name: name,
" + " listA: [ { a: 1
, b: 1.2 } ],
" + " listB: [ { a: 1 ,
b: 1.2 }, { a: 3 , b: 2.3 } ]," + " num: 128
" + "}
"); String expected = "!net.openhft.chronicle.wire.TextWireTest$NestedList {
" + " name: name,
" + " listA: [
" + " { a: 1, b: 1.2 }
" + " ],
" + " listB: [
" + " { a: 1, b: 1.2 },
" + " { a: 3, b: 2.3 }
" + " ],
" + " num: 128
" + "}
"; assertEquals(expected, nl.toString()); OUTER: for (int i = 0; i < 64; i++) { Set<Integer> set = new HashSet<>(); String cs = "!net.openhft.chronicle.wire.TextWireTest$NestedList {
"; int z = i; for (int j = 0; j < 4; j++) { if (!set.add(z & 3)) continue OUTER; switch (z & 3) { case 0: cs += " name: name,
"; break; case 1: cs += " listA: [
" + " { a: 1, b: 1.2 }
" + " ],
"; break; case 2: cs += " listB: [
" + " { a: 1, b: 1.2 },
" + " { a: 3, b: 2.3 }
" + " ],
"; break; case 3: cs += " num: 128,
"; break; } z /= 4; } cs += "}
"; NestedList nl2 = Marshallable.fromString(cs); assertEquals(expected, nl2.toString()); } }

