b: AA
c: {}
d: 
 A: 1
 B: 2
e: end"); try { YamlWire yw = new YamlWire(from); yw.read("a").text(); assertEquals("[
" + " { token: STREAM_START, indent: -1, keys: !!null "" },
" + " { token: DIRECTIVES_END, indent: -1, keys: !!null "" },
