@Override public String toString() { StringBuilder sb = new StringBuilder(); if (querySyncConfiguration != null) sb.append(querySyncConfiguration); if (metricsNameSnakeCase) sb.append("metricsNameSnakeCase: true
"); if (useDomainQualifier) sb.append(DOMAIN_QUALIFIER + ": true
"); if (restPort != null) sb.append(REST_PORT + ": ").append(restPort).append("
"); sb.append("queries:
"); for (MBeanSelector query : getQueries()) sb.append(formatQuery(query)); return sb.toString(); }

@Test public void logging_of_both_request_and_response_validation_works_when_test_fails() { RestAssuredMockMvc.config = new RestAssuredMockMvcConfig().logConfig(new LogConfig(captor, true).enableLoggingOfRequestAndResponseIfValidationFails()); try { given(). standaloneSetup(new PostController()). param("name", "Johan"). when(). post("/greetingPost"). then(). body("id", equalTo(1)). body("content", equalTo("Hello, Johan2!")); fail("Should throw AssertionError"); } catch (AssertionError e) { String writerString = writer.toString(); String headerString = String.format("Request method:	POST%n" + "Request URI:	http://localhost:8080/greetingPost%n" + "Proxy:			<none>%n" + "Request params:	name=Johan%n" + "Query params:	<none>%n" + "Form params:	<none>%n" + "Path params:	<none>%n" + "Headers:		Content-Type=application/x-www-form-urlencoded;charset=%s%n" + "Cookies:		<none>%n" + "Multiparts:		<none>" + "%nBody:			<none>%n" + "%n" + "200%n" + "Content-Type: application/json;charset=UTF-8%n", RestAssuredMockMvcConfig.config().getEncoderConfig().defaultContentCharset()); assertThat(writerString, startsWith(headerString)); assertJsonEqualsNonStrict(writerString.replace(headerString, "").trim(), "{
 "id": 1,
 "content": "Hello, Johan!"
}"); } }

