@Test public void testGenerateDescription2() { JavaSource javaSource; String sourceCode; javaSource = JavaSourceFactory.getInstance().newJavaSource("Configurator"); sourceCode = "package org.lightfish.business.configuration.boundary;
" + "import org.lightfish.business.configuration.entity.Configuration;
" + "import java.util.Arrays;
" + "import javax.annotation.PostConstruct;
" + "import javax.ejb.Singleton;
" + "import javax.enterprise.inject.Produces;
" + "import javax.enterprise.inject.spi.InjectionPoint;
" + "import javax.ejb.Startup;
" + "import javax.inject.Inject;
" + "import org.lightfish.business.configuration.control.ConfigurationStore;
" + "@Startup
" + "@Singleton
" + "public class Configurator {
" + " private Configuration configuration;
" + " @Inject ConfigurationStore configurationStore;
" + " @PostConstruct
" + " public void initialize(){
" + " this.configuration = configurationStore.retrieveConfiguration();
" + " }
" + " @Produces
" + " public int getInteger(InjectionPoint ip) {
" + " return Integer.parseInt(getString(ip));
" + " }
" + " @Produces
" + " public boolean getBoolean(InjectionPoint ip) {
" + " return Boolean.parseBoolean(getString(ip));
" + " }
" + " @Produces
" + " public String getString(InjectionPoint ip) {
" + " String name = ip.getMember().getName();
" + " return this.configuration.get(name);
" + " }
" + " @Produces
" + " public String[] getStringArray(InjectionPoint ip){
" + " return asArray(getString(ip));
" + " }
" + " public String[] getStringArray(String key){
" + " return asArray(getValue(key));
" + " }
" + " public String getValue(String key){
" + " return this.configuration.get(key);
" + " }
" + " public String[] asArray(String value){
" + " return value.split(",");
" + " }
" + "// public Map<String, String> getConfiguration() {
" + "// return configuration;
" + "// }
" + " public int getValueAsInt(String interval) {
" + " return Integer.parseInt(getValue(interval));
" + " }
" + " public void setValue(String key,int interval) {
" + " this.setValue(key, String.valueOf(interval));
" + " }
" + " public void setValue(String key,boolean value) {
" + " this.setValue(key, String.valueOf(value));
" + " }
" + " public void setValue(String key, String value) {
" + " this.configuration.put(key, value);
" + " configurationStore.save(configuration);
" + " }
" + " public void setArrayValue(String key, String[] values) {
" + " StringBuilder sb = new StringBuilder();
" + " for(String value:values){
" + " if(sb.length()!=0){
" + " sb.append(",");
" + " }
" + " sb.append(value);
" + " }
" + " this.setValue(key, String.valueOf(sb.toString()));
" + " }
" + "}
"; javaSource.setSourceCode(sourceCode); JavaSourceContainer.getInstance().add(javaSource); JavaSourceInspector.getInstance().registerExaminer(new ExaminerInject()); JavaSourceInspector.getInstance().registerExaminer(new ExaminerProduces()); JavaSourceInspector.getInstance().examine(); String actual = Description.generateDescription(javaSource); assertTrue(actual.indexOf("ConfigurationStore is injected") > 0); assertTrue(actual.indexOf("Produces Integer") > 0); assertTrue(actual.indexOf("Produces Boolean") > 0); assertTrue(actual.indexOf("Produces String") > 0); assertTrue(actual.indexOf("Produces String[]") > 0); }

@Test public void testConvertCompositeTemplateToKubernetesTemplate() throws IOException { CompositeTemplate template = deserializeCompositeTemplate( getContent("composite.wordpress.kubernetes.yaml")); KubernetesTemplate kubernetesTemplate = fromCompositeTemplateToKubernetesTemplate(template); assertEquals(2, kubernetesTemplate.deployments.size()); assertEquals(2, kubernetesTemplate.services.size()); Service wordpressService = kubernetesTemplate.services.get("wordpress"); Service mysqlService = kubernetesTemplate.services.get("db"); Deployment wordpressDeployment = kubernetesTemplate.deployments.get("wordpress"); Deployment mysqlDeployment = kubernetesTemplate.deployments.get("db"); String wordpressDeploymentSerialized = serializeKubernetesEntity(wordpressDeployment); String mysqlDeploymentSerialized = serializeKubernetesEntity(mysqlDeployment); String wordpressServiceSerialized = serializeKubernetesEntity(wordpressService); String mysqlServiceSerialized = serializeKubernetesEntity(mysqlService); String expectedWordpressDeployment = getContent("kubernetes.wordpress.deployment.yaml"); String expectedWordpressService = getContent("kubernetes.wordpress.service.yaml"); String expectedMysqlDeployment = getContent("kubernetes.mysql.deployment.yaml"); String expectedMySqlService = getContent("kubernetes.mysql.service.yaml"); assertEquals(switchToUnixLineEnds(expectedMysqlDeployment).trim(), mysqlDeploymentSerialized); assertEquals(switchToUnixLineEnds(expectedWordpressService).trim(), wordpressServiceSerialized); assertEquals(switchToUnixLineEnds(expectedWordpressDeployment).trim(), wordpressDeploymentSerialized); assertEquals(switchToUnixLineEnds(expectedMySqlService).trim(), mysqlServiceSerialized); StringBuilder builder = new StringBuilder(); builder.append(expectedWordpressService); builder.append("
"); builder.append(expectedMySqlService); builder.append("
"); builder.append(expectedWordpressDeployment); builder.append("
"); builder.append(expectedMysqlDeployment); builder.append("
"); String kubernetesTemplateSerialized = serializeKubernetesTemplate(kubernetesTemplate); assertEquals(switchToUnixLineEnds(builder.toString()).trim(), kubernetesTemplateSerialized); }

