" + "}%n"); } }

@Test public void logging_of_both_request_with_uri_function_and_response_validation_works_when_test_fails() throws JSONException { RestAssuredWebTestClient.config = new RestAssuredWebTestClientConfig() .logConfig(new LogConfig(captor, true) .enableLoggingOfRequestAndResponseIfValidationFails()); try { given() .standaloneSetup(new PostController()) .contentType(ContentType.URLENC) .when() .post(uriBuilder -> uriBuilder.path("/greetingPost").queryParam("name", "Johan").build()) .then() .body("id", equalTo(1)) .body("content", equalTo("Hello, Johan2!")); fail("Should throw AssertionError"); } catch (AssertionError e) { assertThat(writer.toString(), containsString(UriUtils.encode("Request from uri function", defaultCharset()))); assertThat(writer.toString(), containsString(String.format("Request method:	POST%n"))); String writerString2 = writer.toString(); String headerString2= String.format("Proxy:			<none>%n" + "Request params:	<none>%n" + "Query params:	<none>%n" + "Form params:	<none>%n" + "Path params:	<none>%n" + "Headers:		Content-Type=application/x-www-form-urlencoded%n" + "Cookies:		<none>%n" + "Multiparts:		<none>%n" + "Body:			<none>%n" + "%n" + "200%n" + "Content-Type: application/json;charset=UTF-8%n" + "Content-Length: 34%n" + "%n" ); assertThat(writerString2, containsString(headerString2)); assertJSONEqual(writerString2.replace(writerString2.substring(0, writerString2.indexOf("{")), "").trim(), "{
