@Override public List<Set<V>> getConnectedComponents() { return ConnectedComponents.getConnectedComponents(this); } @Override public String toString() { StringBuilder s = new StringBuilder(); s.append("{
"); s.append("Vertices:
"); List<String> lines = new ArrayList<>(); for (V vertex : outgoingEdges.keySet()) { lines.add(" " + vertex + '
'); } Collections.sort(lines); for (String line : lines) { s.append(line); } s.append("Edges:
"); lines = new ArrayList<>(); for (V source : outgoingEdges.keySet()) { for (V dest : outgoingEdges.get(source).keySet()) { for (E edge : outgoingEdges.get(source).get(dest)) { lines.add(" " + source + " -> " + dest + " : " + edge + "
"); } } } Collections.sort(lines); for (String line : lines) { s.append(line); } s.append('}'); return s.toString(); }
